pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the raw calldata bytes sent in a low-level call to version()
    function testFuzz_property(bytes memory data) public {
        // Keep domain wide; no tight assumptions. However ensure the selector for version() is present
        // so that we exercise external dispatch; allow fuzzer to try many variants including correct selector.
        bytes4 sel = bytes4(keccak256("version()"));
        // construct call data: if data already begins with selector, use it; otherwise prepend selector
        bytes memory calldataForCall;
        if (data.length >= 4) {
            // if first 4 bytes equal selector, use data as-is; else prepend selector to data
            bytes4 first4;
            assembly { first4 := mload(add(data, 32)) }
            if (first4 == sel) {
                calldataForCall = data;
            } else {
                calldataForCall = abi.encodePacked(sel, data);
            }
        } else {
            calldataForCall = abi.encodePacked(sel, data);
        }

        // perform low-level call so we exercise arbitrary calldata shapes
        (bool ok, bytes memory ret) = address(c).call(calldataForCall);

        // The general rule: reference returns a non-empty string and does not revert for ANY calldata
        // We assert that the call succeeded and returned non-empty bytes (string encoding has length > 0)
        // (This is a single assertion reading c's behavior via low-level call result)
        bool successAndNonEmpty = ok && ret.length > 0;
        assertTrue(successAndNonEmpty);
    }
}

