pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the prospective caller and a new number to set
    function testFuzz_property(address caller, uint64 newNumber) public {
        // keep caller wide but avoid zero-address because EOA zero cannot be impersonated by vm.prank
        // allow zero so mutation that compares to address(0) can be explored, but vm.prank(address(0)) is invalid
        // bound newNumber to full range of uint64 (no restriction)

        // Arrange: pick a caller. If caller == address(0) we skip impersonation because vm.prank(address(0)) is not valid.
        // We'll instead use a real EOA for calls; prefer non-depositor caller to test enforcement.
        address depositor = C.DEPOSITOR_ACCOUNT();

        // Choose an actor to act as the caller for the call. If fuzzed caller equals address(0), substitute a non-depositor EOA
        address actor = caller;
        if (actor == address(0)) {
            // choose some non-depositor account
            actor = address(0xBEEF);
        }

        // Ensure actor is not the depositor to test restriction: allow the fuzzer to still sometimes pick the depositor
        // but do not hard-code a depositor value; only substitute when equal to depositor to keep wide.
        if (actor == depositor) {
            actor = address(0xBEEF);
        }

        // Act: attempt to call setL1BlockValues as actor via vm.prank
        vm.prank(actor);
        bool ok;
        try c.setL1BlockValues(
            newNumber,
            uint64(block.timestamp),
            uint256(0),
            bytes32(0),
            uint64(0),
            bytes32(0),
            uint256(0),
            uint256(0)
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: On the reference contract, only the depositor can succeed in calling setL1BlockValues.
        // Therefore for any actor that is not the depositor, the call must fail (ok == false).
        // This single assertion observes c via its public DEPOSITOR_ACCOUNT getter to determine the depositor.
        // If the mutant changed the check to address(0), some non-depositor actor calls will unexpectedly succeed,
        // causing this assertion to fail for those inputs — thus distinguishing mutant from reference.
        assertTrue(!ok);
    }
}

