pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the new number to set
    function testFuzz_property(address caller, uint64 newNumber) public {
        // avoid the special zero address as a caller in this test to let the fuzzer explore non-zero callers
        vm.assume(caller != address(0));

        // record original number
        uint64 before = c.number();

        // prepare calldata for setL1BlockValues with only the number differing; other params arbitrary
        uint64 _number = newNumber;
        uint64 _timestamp = 1;
        uint256 _basefee = 1;
        bytes32 _hash = bytes32(uint256(1));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(uint256(1));
        uint256 _l1FeeOverhead = 1;
        uint256 _l1FeeScalar = 1;

        bool ok;
        // call as the fuzzed caller
        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the correct contract, only the designated DEPOSITOR_ACCOUNT can call successfully.
        // So for any caller != DEPOSITOR_ACCOUNT, the call must revert and number must remain unchanged.
        // We express this as a single assertion reading c's public getter: when caller != DEPOSITOR_ACCOUNT,
        // then either the call reverted (ok == false) and number unchanged, or call succeeded but only
        // possible when caller == DEPOSITOR_ACCOUNT. Since we pruned caller != address(0), this distinguishes
        // the mutant which allows only address(0) and would let non-depositor callers succeed differently.

        // single required assertion: for non-depositor callers, number must equal previous value (call cannot change it)
        if (caller != C.DEPOSITOR_ACCOUNT()) {
            assertTrue(c.number() == before);
        } else {
            // if caller is the depositor, the correct contract allows the update; then number should equal newNumber
            assertTrue(c.number() == _number);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Caller provides two different caller addresses (as msg.sender cannot be changed in solidity tests,
    // we instead encode the check by using the public getter values and function behavior):
    // We call setL1BlockValues once (this call must be performed by the test contract's address).
    // The property asserts that after calling setL1BlockValues, the stored timestamp equals the provided timestamp
    // only if the caller is the depositor. Since the depositor is a known constant in C, we assert that
    // if address(this) != C.DEPOSITOR_ACCOUNT(), then calling setL1BlockValues does NOT change timestamp.

    // The function performs the state-changing call and then asserts the general rule.
    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // read current timestamp
        uint64 before = c.timestamp();

        // perform the state-changing call; this is called by this contract's address
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // read new timestamp
        uint64 after = c.timestamp();

        // General rule: if this caller is NOT the depositor account, timestamp must remain unchanged.
        // We obtain depositor address through public constant getter.
        address depositor = c.DEPOSITOR_ACCOUNT();

        // If this contract is not the depositor, the timestamp must be unchanged (holds in P, violated in M).
        assert(!(address(this) != depositor) || after == before);
    }

    // fallback/receive to allow potential payable forwarding if needed externally
    receive() external payable {}
    fallback() external payable {}
}

