pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params include the deciding values: _number and _timestamp
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // keep domain wide; no restrictive assumes so fuzzer can find _number != _timestamp
        // call must be made by the depositor account
        address depositor = C.DEPOSITOR_ACCOUNT();
        vm.prank(depositor);
        // drive the contract
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        // The universal property: contract.timestamp() equals the provided _timestamp for all inputs
        // This will hold for the reference implementation, but fail for the mutant when _timestamp != _number
        assertTrue(c.timestamp() == _timestamp);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Attempt to call setL1BlockValues from a provided caller address and assert that it only succeeds when caller == DEPOSITOR_ACCOUNT.
    // We observe success via whether the call returns (no revert) by using low-level call and its returned boolean.
    function runTest(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Build calldata for c.setL1BlockValues(...)
        bytes memory payload = abi.encodeWithSelector(c.setL1BlockValues.selector, _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        // Perform low-level call from this contract but set msg.sender via a simple approach: use an external call to c from this contract
        // Since we cannot change msg.sender in the EVM here, we interpret 'caller' as the address we expect to be allowed.
        // Instead we detect whether the call would succeed when made by the true depositor by comparing caller to the known depositor getter.

        // Read the designated depositor address from contract c via its public constant getter
        address depositor = c.DEPOSITOR_ACCOUNT();

        // The property: only the designated depositor can call successfully.
        // We check this by asserting that (caller == depositor) is equivalent to a successful low-level call initiated from this contract
        // when we set things up so that only if 'caller' equals depositor we consider the call allowed.
        // Since we cannot change msg.sender for the low-level call from this contract, we instead perform the call and rely on two facts:
        // - On the original contract P, only depositor address is allowed; any other msg.sender will revert.
        // - For our low-level call (from this contract), it will either revert (not allowed) or succeed (allowed). We then assert that success implies caller==depositor.

        // Execute the call from this contract and capture whether it succeeded.
        (bool success, ) = address(c).call(payload);

        // The invariant that must hold on the original contract: success is true if and only if the provided caller equals depositor.
        // However, since our actual msg.sender is this contract, the only-way success can be true on P is when this contract equals depositor.
        // To make this a general rule about the relation between 'caller' parameter and depositor, we require that success ==> caller == depositor.
        // This is a simple comparison that distinguishes the mutant which inverts the check (it would allow non-depositor callers).
        assert(!success || (caller == depositor));
    }

    // Fallbacks to accept any plain Ether transfers if needed by tests.
    receive() external payable {}
    fallback() external payable {}
}
